  "name": "Full Page Screenshot",
  "version": "1.0",
  "description": "Takes a screenshot of the entire webpage, not just the visible viewport.",
  "permissions": [
    "activeTab",
    "downloads",
    "scripting"
  ],
  "action": {
    "default_popup": "popup.html",
    "default_icon": {
      "16": "icon.png",
      "48": "icon.png",
      "128": "icon.png"
